INSERT INTO definition (id, entry_id, lang, text, source) VALUES (9, 121, 'tr', 'Buna gerek var mı? Tırmanıcılık çalışmalarında karşımıza çıkıyormuş: Dağcılık ve tırmanış ipleri; perlon ip, perlon bant, perlon kayış gibi türlere ayrılır. Perlon ip çeşitleri, ağırlıklı olarak kaya yüzeylere tırmanırken tercih edilir ve kalın tasarımları sayesinde en keskin kayalıklarda dahi herhangi bir deformasyona uğramaması ile size büyük bir güvenlik sağlar.', 'decathlon');
